import ch.jalu.configme.exception.ConfigMeException;
import ch.jalu.configme.properties.Property;
import org.junit.Test;

import java.util.List;
import java.util.Map;

import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class PropertyListBuilderTest {

    @Test
    public void addPropertyTest() {
        PropertyListBuilder builder = new PropertyListBuilder();
        Property<Object> property1 = new Property<Object>("path1", "defaultValue1");
        builder.add(property1);

        List<Property<?>> properties = builder.create();
        assertEquals("Should only have one property", 1, properties.size());
        assertEquals("Added property should be in properties", property1,  properties.get(0));
    }

    @Test(expected = ArgumentNullException.class) 
    public void addNullPropertyTest(){
        PropertyListBuilder builder = new PropertyListBuilder();
        builder.add(null);
    }

    @Test
    public void createPropertyListTest() {
        PropertyListBuilder builder = new PropertyListBuilder();
        List<Property<?>> propertyList1 = builder.create();
        List<Property<?>> propertyList2 = builder.create();
        assertNotSame(propertyList1, propertyList2);
    }

    @Test
    public void getRootEntriesEmptyTest() {
        PropertyListBuilder builder = new PropertyListBuilder();
        Map<String, Object> entries = builder.getRootEntries();
        assertTrue("Created Map should be empty", entries.isEmpty());
    }

    @Test
    public void getRootEntriesNonEmptyTest() {
        PropertyListBuilder builder = new PropertyListBuilder();
        Property<Object> property1 = new Property<Object>("mockPath", 890);
        builder.add(property1);
        Map<String, Object> entries = builder.getRootEntries();
        assertEquals("Map should have one entry", 1, entries.size());
        assertTrue("Map should contain the property's path", entries.containsKey(property1.getPath()));
    }

}
